window.EB_SB_ADD({"sf2e-anachronism.tales-from-the-vast-bestiary/FKpcnpWbtbpbXL7c":{"abilities":[{"n":"Construct Armor","a":null,"c":"defensive","t":[],"f":"","d":"<p>Like normal objects, an Acsie enforcer has Hardness. This Hardness reduces any damage it takes by an amount equal to the Hardness. Once an enforcer is reduced to less than half its Hit Points, or immediately upon being damaged by a critical hit, its construct armor breaks, removing the Hardness and reducing its Armor Class to 15.</p>"},{"n":"Shard Spray","a":"2","c":"offensive","t":["manipulate"],"f":"","d":"<p>The Acsie enforcer hurls projectiles at a target within 30 feet, dealing 2d6 piercing damage (DC 17 basic Reflex save). On failure, the target becomes suppressed until the beginning of the Acsie enforcer's next turn. Enemies within 10 feet of the target also take 2 piercing damage (DC 17 basic Reflex save).</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/63Jn2gSyeDEem19d":{"lang":["Acsie"],"gear":["Integrated Shock Pad","Integrated Battery (Commercial) (2)"],"abilities":[{"n":"Sonic Purification","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A non-Acsie creature or object moves and is within 60 feet of the servitor</p><hr><p><strong>Effect</strong> The servitor attempts a sonic cleaner ranged Strike against the triggering creature.</p>"},{"n":"Cleansing Burst","a":null,"c":"offensive","t":[],"f":"","d":"<p>When the servitor's sonic cleaner hits a creature, it removes any dirt or other debris. If the target is a living creature, it gains weakness 2 to sonic until the end of the servitor's next turn and gains a +1 circumstance bonus to saves against disease and poisons for 1 hour.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/5cHzURn6ShrV8tzZ":{"lang":["Common","Vesk"],"gear":["Pulsecaster Pistol","Moonside-250 Uniform","Battery (Commercial) (2)"],"abilities":[{"n":"Hang in There!","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> An ally within 30 feet takes damage</p><hr><p><strong>Effect</strong> The admin employee of the month shouts a corporate slogan at their ally, granting them 10 temporary Hit Points. These temporary Hit Points last for 1 round.</p>"},{"n":"Peppy Hustle","a":null,"c":"defensive","t":[],"f":"","d":"<p>An admin employee of the month ignores difficult terrain and greater difficult terrain inside Moonside-250.</p>"},{"n":"Corporate Loyalty","a":null,"c":"offensive","t":[],"f":"","d":"<p>An admin employee of the month deals an additional 1d6 precision damage to creatures who aren't affiliated with their organization.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/suiEBjlMqLn4Gusi":{"description":"<p>Hidden launch tubes fire darts filled with anesthetics at a 10-foot square.</p>","disable":"<p>DC 18 Thievery (trained)</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Dart Volley","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Pressure is applied to the floor tiles</p><hr><p><strong>Effect</strong> The trap shoots a wave of darts targeting the entire area as a single attack. Creatures in the affected area take 4d8+10 nonlethal poison poison damage and must attempt a DC 21 Reflex save. The trap also triggers an audible alarm.</p><hr><p><strong>Critical Success</strong> The creature takes no damage.</p>\n<p><strong>Success</strong> The creature takes half damage.</p>\n<p><strong>Failure</strong> The creature takes full damage and is slowed 2.</p>\n<p><strong>Critical Failure</strong> The creature takes double damage and is slowed 3.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/3Fi9xhh5YlFmyuKe":{"lang":["Coshyco"],"gear":["Arc Pistol","Knife","Shock Pad","Armored Coat","Maker's Toolkit (Commercial)","Battery (Commercial) (2)","Battery (Commercial)"],"abilities":[{"n":"Absorb Shock","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Arnyn would take bludgeoning damage</p><hr><p><strong>Effect</strong> The coshyco absorbs the shock of the blow into its flesh, avoiding broken bones or other significant damage. They gain resistance 4 to bludgeoning for the triggering attack.</p>"},{"n":"Adjust Shape","a":"2","c":"offensive","t":["manipulate"],"f":"","d":"<p>Arnyn rearranges their skeleton to adapt to their circumstances. They choose between squat, lanky, or flexible. If they take on the squat shape, they gain a +2 circumstance bonus to Athletics checks to Force open. If they choose lanky, they gain a +2 circumstance bonus to Acrobatics checks to Squeeze. If they choose flexible, their reach increases to 10 feet with held melee weapons.</p>"},{"n":"Quick Tinker","a":"1","c":"offensive","t":["manipulate"],"f":"","d":"<p>Arnyn adjusts one of her weapons with the tech trait. Her next attack before the start of her next turn deals an additional 1d6 electricity damage.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/4qBA870aD789efnm":{"lang":["Common","Draconic","Triaxian"],"lore":[["Corporate Lore",11],["Life Science Lore",18]],"gear":["Advanced Injection Rifle","Estex Suit","Dart (20)"],"notes":{"per":"low-light vision"},"abilities":[{"n":"Booster","a":"1","c":"offensive","t":[],"f":"","d":"<p>Biran boosts an ally he can see within 100 feet. Until the start of his next turn, the target of his Booster gains a +1 status bonus to AC and a +5-foot status bonus to Speeds.</p>"},{"n":"Inhibitor","a":"2","c":"offensive","t":[],"f":"","d":"<p>Biran targets a creature with a specially crafted cocktail of chemicals to inhibit their performance. Biran makes a ranged injection rifle Strike; on a hit, the target takes damage as normal and must attempt a DC 24 Fortitude save.</p><hr><p><strong>Critical Success</strong> The creature is unaffected.</p>\n<p><strong>Success</strong> The creature is Sickened 1.</p>\n<p><strong>Failure</strong> The creature is Slowed 1 for 1 round.</p>\n<p><strong>Critical Failure</strong> The creature is Sickened 2 and Slowed 2 for 1 round.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/4ZFkUPreQRq0sonB":{"description":"<p>The rivers and streams bubble and boil over, flooding the streets of the town with scalding water.</p>","disable":"<p>DC 22 Athletics (trained) to Climb or Swim to safety, or DC 25 Athletics (trained) to pull a creature to safety</p>","reset":"<p>The trap deactivates and resets after 3 rounds.</p>","routine":"<p>(1 action) A wave of scalding, 20-foot-deep water surges through town, dealing 2d8+9 fire damage to all creatures in the water (DC 21 basic Reflex save). Creatures in the water must hold their breath or begin drowning.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Flash Flood","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The Guiding Intelligence activates the hazard</p><hr><p><strong>Effect</strong> Scalding water deals 1d10 fire damage to all creatures. The hazard then rolls initiative.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/BvS1cWE6Mo1viBNQ":{"abilities":[{"n":"Reactive Strike","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Flyby Flurry","a":"2","c":"offensive","t":[],"f":"","d":"<p>The braantu flies up to its Speed in a line and makes a wing spur Strike against up to three creatures in the line. If the Strike hits, the creature takes damage and is off-guard until the beginning of the braantu's next turn.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/Mq6JdLWdUL6NI01r":{"gear":["Integrated Advanced Fangblade","Integrated Advanced Scattergun","Integrated Armored Coat","Projectile Ammo (36)"],"notes":{"per":"darkvision"}},"sf2e-anachronism.tales-from-the-vast-bestiary/uZHdo8Vlc0z7deYA":{"notes":{"hp":"hydra regeneration","ac":"all-around vision"},"abilities":[{"n":"Skymetal Metamorphosis Orichalcum","a":null,"c":"interaction","t":[],"f":"","d":"<p>When Bronco has only two heads remaining, he is Quickened. He can use the extra action only to Stride or Strike.</p>"},{"n":"All-Around Vision","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>This monster can see in all directions simultaneously and therefore can't be flanked.</p></p>"},{"n":"Hydra Regeneration","a":null,"c":"defensive","t":[],"f":"","d":"<p>Bronco has regeneration equal to 3 × the number of heads it has. If a hydra's body is missing any heads and the remaining stumps have not been cauterized, the hydra attempts a DC 29 Fortitude save after it regains Hit Points from regeneration. On a success, one uncauterized stump regrows two heads; on a critical success, two uncauterized stumps regrow into two heads each. The hydra can never grow more than double the number of heads it ordinarily has. The hydra's regeneration only fully deactivates if all its heads are severed and all stumps are cauterized, at which point it dies.</p>"},{"n":"Head Regrowth","a":null,"c":"defensive","t":[],"f":"","d":"<p>Bronco has five heads. A creature can attempt to sever one of the hydra's heads by specifically targeting it and dealing damage equal to the head's Hit Points. A head that isn't completely severed returns to full Hit Points at the end of any creature's turn.</p>\n<p>Bronco can regrow a severed head using hydra regeneration. A creature can prevent this regrowth by dealing acid or fire damage to the stump, cauterizing it. Single-target acid or fire effects need to be targeted at a specific stump, but effects that deal splash damage or affect areas covering the hydra's whole space cauterize all stumps if they deal acid or fire damage. If the attack that severs a head deals any acid or fire damage, the stump is cauterized instantly. If all five heads are severed and cauterized, Bronco dies.</p>"},{"n":"Reactive Heads","a":null,"c":"defensive","t":[],"f":"","d":"<p>Bronco gains an extra reaction per round for each of its heads beyond the first, which it can use only to make Reactive Strikes. It can't use more than 1 reaction on the same triggering action, even if a creature leaves several squares within its reach, and the hydra must use a different head for each Reactive Strike it makes. Whenever one of the hydra's heads is severed, the hydra loses 1 of its extra reactions per round.</p>"},{"n":"Reactive Strike","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature within your reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p>You lash out at a foe that leaves an opening. Make a melee Strike against the triggering creature. If your attack is a critical hit and the trigger was a manipulate action, you disrupt that action. This Strike doesn't count toward your multiple attack penalty, and your multiple attack penalty doesn't apply to this Strike.</p>"},{"n":"Stargut Hydra Heads","a":null,"c":"defensive","t":[],"f":"","d":"<p><strong>HP</strong> (head) 22, head regrowth</p>\n<p><strong>Immunities</strong> area damage</p>\n<p><strong>Weaknesses</strong> slashing 10</p>"},{"n":"Vomit Meteorites","a":"2","c":"offensive","t":[],"f":"","d":"<p>Bronco lurches its entire body, spewing forth chunks of meteorite in a 30-foot cone that deal 5d6 bludgeoning damage to all creatures in the area (DC 25 basic Reflex). The area becomes difficult terrain for 1 minute, though a creature can use an Interact action to clear one square of the rubble. Bronco can't Vomit Meteorites for 1d4 rounds.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/YDFBJtOBR0iGcql5":{"lang":["Daemonic","Telepathy 100 feet"],"focus":1,"abilities":[{"n":"Telepathy 100 feet","a":null,"c":"interaction","t":["aura","magical","mental"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"At-Will Spells","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>The monster can cast its at-will spells any number of times without using up spell slots.</p></p>"},{"n":"Cacodaemonia","a":null,"c":"offensive","t":["disease"],"f":"","d":"<p>The cacodaemon can telepathically communicate with the afflicted creature at any distance on the same plane.</p>\n<p><strong>Saving Throw</strong> DC 17 Fortitude</p><hr><p><strong>Stage 1</strong> carrier (1 day)</p>\n<p><strong>Stage 2</strong>Stupefied 1 (1 day)</p>\n<p><strong>Stage 3</strong> Stupefied 2 (1 day)</p>"},{"n":"Change Shape","a":"1","c":"offensive","t":["concentrate","divine","polymorph"],"f":"","d":"<ul><li><p><strong>Lizard</strong></p><ul><li><p><strong>Speed</strong> 20 feet</p></li><li><p><strong>Melee</strong> jaws +8 (agile, finesse), <strong>Damage</strong> 1d8+1 piercing</p></li></ul></li><li><p><strong>Octopus</strong></p><ul><li><p><strong>Size</strong> Small</p></li><li><p><strong>Speed</strong> 20 feet, swim 30 feet</p></li><li><p><strong>Skills</strong> Athletics +6</p></li><li><p><strong>Melee</strong> tentacle +8 (finesse), <strong>Damage</strong> 1d8+1 bludgeoning plus Grab</p></li><li><p><strong>Melee</strong> beak +8 (agile, finesse), <strong>Damage</strong> 1d6 piercing plus 2 poison</p></li></ul></li><li><p><strong>Scorpion</strong></p><ul><li><p><strong>Size</strong> Small</p></li><li><p><strong>Speed</strong> 30 feet</p></li><li><p><strong>Skills</strong> Athletics +6</p></li><li><p><strong>Melee</strong> pincer +8 (agile, finesse), <strong>Damage</strong> 1d6+1 bludgeoning plus Grab</p></li><li><p><strong>Melee</strong> stinger +8 (agile, finesse), <strong>Damage</strong> 1d6+1 piercing plus 1d4 poison</p></li></ul></li></ul><hr><p><p>The monster changes its shape indefinitely. It can use this action again to return to its natural shape or adopt a new shape. Unless otherwise noted, a monster cannot use Change Shape to appear as a specific individual. Using Change Shape counts as creating a disguise for the Impersonate use of Deception. The monster's transformation automatically defeats Perception DCs to determine whether the creature is a member of the ancestry or creature type into which it transformed, and it gains a +4 status bonus to its Deception DC to prevent others from seeing through its disguise. Change Shape abilities specify what shapes the monster can adopt. The monster doesn't gain any special abilities of the new shape, only its physical form. For example, in each shape, it replaces its normal Speeds and Strikes, and might potentially change its senses or size. Any changes are listed in its stat block.</p></p>"},{"n":"Soul Lock","a":"3","c":"offensive","t":["death","divine"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p><hr><p><strong>Effect</strong> The cacodaemon ingests the soul of a sentient creature within 30 feet that died within the last minute. When they do, the cacodaemon grows a fist-sized soul gem (Hardness 2, HP 8) in their gut and can regurgitate it at any time as an Interact action. Destroying the gem frees the soul within but doesn't return the deceased creature to life. If a caster attempts to return to life a creature whose soul is trapped within a soul gem, they fail unless they succeed at a DC 30 Religion check. A success causes the soul gem to shatter so the creature is returned to life as normal for the spell.</p>\n<p>A fiend can Interact to ingest a soul gem it is holding, condemning the soul to the fiend's home plane. The fiend gains fast healing 5 for 1 minute.</p>\n<p>Effect: Soul Lock (Healing)</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/rA6ZwEATCgbw45Yc":{"abilities":[{"n":"Gnaw Rock","a":null,"c":"interaction","t":["exploration"],"f":"","d":"<p>A cave khefak chews on rock to feed, dealing 4 piercing damage every 10 minutes to the object. This damage ignores 10 points of Hardness. If a khefak doesn't spend at least 1 hour Gnawing Rock per day, it begins to starve until it spends 10 minutes Gnawing Rock.</p>"},{"n":"Cave Radiation","a":null,"c":"defensive","t":["aura","radiation"],"f":"","d":"<p>10 feet. A cave khefak gives off an aura of mild radiation. A creature that starts its turn in the emanation must succeed at a DC 20 Fortitude save or take 1d6 poison damage and become Sickened 1.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/xSoS4hcxbJQ3LHfv":{"description":"<p>Years of mining and erosion have made the walls and ceiling of this 20-foot square unstable, causing frequent rockslides.</p>","disable":"<p>DC 21 Survival (trained) to map a path that doesn't cause any rockfalls, or DC 25 Crafting (expert) or Engineering Lore (trained) to build a support and maintain the integrity of the tunnel</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Rockslide","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature steps into the area or causes any sort of disruption within the area (such as firing a projectile)</p><hr><p><strong>Effect</strong> The supports maintaining the tunnel collapse, bringing a deluge of earth. All creatures in the area take 4d6 bludgeoning damage with a DC 18 basic Reflex save. The area becomes greater difficult terrain.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/NcCzuhhR6bE18n2c":{"description":"<p>Chemical vials are rigged to break when someone opens the door.</p>","disable":"<p>DC 18 Thievery (trained) to cut the trip wires around the door without shattering the capsules.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Chemical Reaction","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature opens the door to area <strong>A13</strong></p><hr><p><strong>Effect</strong> The capsules shatter, and noxious fumes fill the area. All creatures in a 15-foot emanation centered on the door must succeed at a DC 18 Fortitude save or become Sickened 1; the emanation leaves behind a cloud of chemicals with the effect of mist for 3 rounds.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/YWRl0Ae5luYHyNsB":{"lang":["Coshyco"],"lore":[["Farming Lore",5]],"gear":["Knife"],"abilities":[{"n":"Absorb Shock","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The coshyco villager would take bludgeoning damage</p><hr><p><strong>Effect</strong> The coshyco absorbs the shock of the blow into its flesh, avoiding broken bones or other significant damage. They gain resistance 2 to bludgeoning for the triggering attack.</p>"},{"n":"Adjust Shape","a":"2","c":"offensive","t":["manipulate"],"f":"","d":"<p>The coshyco villager rearranges their skeleton to adapt to their circumstances. They choose between squat, lanky, or flexible. If they take on the squat shape, they gain a +2 circumstance bonus to Athletics checks to Force open. If they choose lanky, they gain a +2 circumstance bonus to Acrobatics checks to Squeeze. If they choose flexible, their reach increases to 10 feet with held melee weapons.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/AwWFBOHmBRyeLtsW":{"description":"<p>This 20-foot square of ground is cobwebbed with cracks and fissures and crumbles when a creature steps on it.</p>","disable":"<p>DC 16 Survival to collapse safely, or DC 20 Crafting (trained) to shore up the area enough to pass over without collapsing it</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Long Fall","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature steps onto the cracked earth</p><hr><p><strong>Effect</strong> The creature fractures the thin crust of earth and falls through. That creature can use the Grab an edge reaction to avoid falling, as long as it's adjacent to an edge. Otherwise, it takes falling damage (typically 25 bludgeoning damage for a 50-foot drop).</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/pofXR6mCcgwvcbPC":{"abilities":[{"n":"Crystallization","a":null,"c":"interaction","t":[],"f":"","d":"<p>The crystalline ooze can Hide in natural environments even if it doesn't have cover, making it indistinguishable from other clusters of crystals.</p>"},{"n":"Entangling Sludge","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The crystalline ooze is hidden via crystallization, and a creature attempts to forage or mine it</p><hr><p><strong>Effect</strong> The crystalline ooze melts into sludge that covers the creature. The triggering creature becomes Clumsy 1 and takes a –5-foot circumstance penalty to its Speeds for 1 hour or until the sludge is removed. The ooze gains a +2 circumstance bonus to checks to Grab creatures covered in sludge. The triggering creature or allies adjacent to it can remove the sludge with a total of 3 Interact actions. These actions don't need to be consecutive or made by the same creature.</p>"},{"n":"Constrict","a":"1","c":"offensive","t":[],"f":"","d":"<p>2d6+7 bludgeoning, DC 18 basic Fortitude</p><hr><p><p>The monster deals the listed amount of damage to any number of creatures Grabbed or Restrained by it. Each of those creatures can attempt a basic Fortitude save with the listed DC.</p></p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/vUXrP3bBLMN7sndD":{"description":"<p>The merged barathu twitches and groans, trying to stop others from rescuing them.</p>","disable":"<p>DC 17 Athletics (trained) to hold the barathu's tentacles down until they give up, DC 19 Diplomacy (expert) to plead with the barathu to stop; two total successes (using any skills) are required to disable the haunt</p>","reset":"<p>The hazard resets automatically after a few moments out of combat, healing only if fed.</p>","routine":"<p>(3 actions) The barathu attempts to Grab up to two creatures within 10 feet with a +14 Athletics modifier, then squeezes each creature it has Grabbed, dealing 1d10+4 bludgeoning damage. The barathu doesn't apply a multiple attack penalty to the second attempt to Grab.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Moan","a":"r","c":"defensive","t":["emotion","fear","mental"],"f":"","d":"<p><strong>Trigger</strong> A creature attacks an employee</p><hr><p><strong>Effect</strong> The barathu moans and squirms, attempting to ward off the attackers. All non-employee creatures within 30 feet must succeed at a DC 18 Will save or be Frightened 1 for as long as the hazard remains active. The barathu then rolls initiative.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/tanRfKmub0E61I8q":{"abilities":[{"n":"Derelict Spark","a":"2","c":"offensive","t":["electricity"],"f":"","d":"<p>A wave of electricity bursts from the derelict harvester's malfunctioning power core. All creatures in a 20-foot cone must attempt a DC 21 Reflex save.</p><hr><p><strong>Critical Success</strong> The creature takes no damage.</p>\n<p><strong>Success</strong> The creature takes 1d6 electricity damage.</p>\n<p><strong>Failure</strong> The creature takes 2d6 electricity damage and is Slowed 1 for 1 round.</p>\n<p><strong>Critical Failure</strong> The creature takes 4d6 electricity damage and is Slowed 2 for 1 round.</p>"},{"n":"Trample","a":"3","c":"offensive","t":[],"f":"","d":"<p>Large or smaller, thresher blade, DC 21 basic Reflex</p><hr><p><p>The monster Strides up to double its Speed and can move through the spaces of creatures of the listed size, Trampling each creature whose space it enters. The monster can attempt to Trample the same creature only once in a single use of Trample. The monster deals the damage of the listed Strike, but trampled creatures can attempt a basic Reflex save at the listed DC (no damage on a critical success, half damage on a success, double damage on a critical failure).</p></p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/TBNHBNLPwC0G9eOJ":{"lore":[["The Devourer Lore",14]],"gear":["Boom Pistol","Fangblade","Armored Coat","Battery (Commercial) (2)"],"abilities":[{"n":"Destructive Whirlwind","a":"3","c":"offensive","t":[],"f":"","d":"<p>The Devourer cultist Strides and Strikes twice with their fangblade. These Strikes can be against any creatures the cultist passes adjacent to during their movement. On a hit, the creature is Off-Guard until the beginning of the cultist's next turn.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/O96L4EmgcoL8ysrc":{"description":"<p>This swirling column of glowing red light is enchanted with the unholy magic of the Devourer. Looking into its depths shows any creature the power of true devastation, filling them with longing and despair.</p>","disable":"<p>DC 19 Athletics or DC 19 Medicine to revive an affected creature, DC 22 Occultism or DC 22 Performance to weave your own message into the projection, DC 24 Arcana or DC 24 Computers to disrupt the projections, or DC 25 Religion to invoke your deity for protection</p>","routine":"<p>(3 actions) The trap uses Devastation's Truth to try to incapacitate all creatures in the worship chamber, then makes a Devourer's maw Strike against a creature in range that resisted the trap's effects.</p>","stealthNote":"<p>or <em>detect magic</em></p>","abilities":[{"n":"Initiation","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Any uninitiated creature enters the worship chamber</p><hr><p><strong>Effect</strong> The trap makes a Devourer's maw Strike against the triggering creature. The trap then rolls initiative.</p>"},{"n":"Devastation's Truth","a":"2","c":"offensive","t":["incapacitation"],"f":"","d":"<p>The Devourer's temptation manifests an intrusive vision of destruction and doom, attempting to awe all who experience it with the power of the Devourer and the inevitability of death for them and all their loved ones. All uninitiated creatures in the worship chamber must attempt a DC 24 Will save.</p><hr><p><strong>Critical Success</strong> The creature is unaffected and can immediately attempt to help an affected creature as a reaction (see Disable).</p>\n<p><strong>Success</strong> The creature is unaffected.</p>\n<p><strong>Failure</strong> The creature takes 2d8+9 mental damage and is Fascinated until a creature revives them. The creature is then immune to Devastation's Truth for 24 hours.</p>\n<p><strong>Critical Failure</strong> The creature takes 4d8+18 mental damage, is fascinated until a creature revives them, and is Stupefied 2 for 24 hours. The creature is then immune to Devastation's Truth for 24 hours.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/a9mnXJ2URQkqLSqe":{"lang":["Daemonic","telepathy 100 feet"],"abilities":[{"n":"Ripple of Pestilence","a":null,"c":"defensive","t":["aura","disease"],"f":"","d":"<p>15 feet. The disteadaemon intensifies pestilence within the aura, imparting a –2 status penalty to saves against disease on all living creatures in its aura.</p>"},{"n":"Disteadaemon Parasites","a":null,"c":"offensive","t":["disease"],"f":"","d":"<p><strong>Saving Throw</strong> DC 17 Fortitude</p>\n<p><strong>Stage 1</strong> Sickened 1 (1 day)</p>\n<p><strong>Stage 2</strong> sickened 1 and Fatigued (1 day)</p>\n<p><strong>Stage 3</strong> Sickened 2 and fatigued (1 day)</p>"},{"n":"Foul Water Spray","a":"2","c":"offensive","t":[],"f":"","d":"<p>The disteadaemon sprays polluted water in a 15-foot cone, exposing all living creatures in the area to disteadaemon parasites. If a target is currently afflicted with any disease, it must immediately attempt a Fortitude save against it, increasing its progression to the next stage on a failure.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/ppXLVjsdWMYW5UeG":{"lang":["Azlanti","Common"],"lore":[["Warfare Lore",21]],"gear":["Advanced Sihedron Guard Armor","Integrated Aeon Stone (Life-Giving)","+1 Weapon Potency Crystal (Solar Flare)","Striking Crystal (Commercial) (Solar Flare)","Gluon Crystal (Tactical) (Solar Flare)","Medpatch (Tactical)"],"notes":{"ac":"regeneration 10 (deactivated by fire)"},"abilities":[{"n":"Personal Gravity","a":null,"c":"interaction","t":[],"f":"","d":"<p>Whenever Xaria makes a critical hit with her solar weapon or solar shot Strikes, she can attempt to Trip the target as a free action using Athletics, even if she doesn't have a free hand and isn't adjacent to the target.</p>"},{"n":"Reactive Strike","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Through Service, Transformation","a":"r","c":"defensive","t":["divine"],"f":"","d":"<p><strong>Trigger</strong> Xaria is reduced to 0 Hit Points, but not from an effect that leaves no remains (like promession)</p><hr><p><strong>Effect</strong> Instead of falling, Xaria is transformed into the Exkruvite. This transformation is permanent, and her soul is consumed in the process.</p>"},{"n":"Aeon Flight","a":"2","c":"offensive","t":["concentrate"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p><hr><p><strong>Effect</strong> The exkruvite gains a fly Speed for 1 minute equal to her Speed.</p>"},{"n":"Aeon Throne Aggrandizement","a":"1","c":"offensive","t":[],"f":"","d":"<p>Xaria attempts to Demoralize a creature. If she succeeds, the dominus then makes a solar shot Strike.</p>"},{"n":"Binaric Assault","a":"2","c":"offensive","t":["flourish","solarian"],"f":"","d":"<p>Xaria attempts a solar weapon Strike and a solar shot Strike, each using her current multiple attack penalty. These attacks can be made in any order. This counts as two attacks when calculating her multiple attack penalty.</p>"},{"n":"Flicker Strike","a":"2","c":"offensive","t":["solarian","teleportation"],"f":"","d":"<p>Xaria attempts a solar weapon Strike. On a success, she chooses a creature within 35 feet. She immediately teleports to any vacant square within 35 feet and attempts a solar weapon Strike on a creature within reach. If the initial Strike fails, she doesn't teleport and the action ends.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/02LDFGeV0zA4sPkC":{"abilities":[{"n":"Lifesense","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Lifesense allows a monster to sense the vital essence of living and undead creatures within the listed range. The sense can distinguish between the vitality energy animating living creatures and the void energy animating undead creatures, much as sight distinguishes colors.</p></p>"},{"n":"Dead Zone","a":null,"c":"defensive","t":["aura","occult"],"f":"","d":"<p>30 feet. The area bristles with chaotic terrain torn from the Drift. The area is zero-gravity. Creatures that enter or begin their turn in the emanation take 4d6 void damage (DC 22 basic Fortitude save).</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Driftdead Creation","a":null,"c":"offensive","t":[],"f":"","d":"<p>Living humanoids killed in the Drift by a composite rise as driftdead after 1d4 rounds, controlled by the driftdead composite that killed it.</p>"},{"n":"Ripping Blast","a":"2","c":"offensive","t":["attack"],"f":"","d":"<p>The composite's claws rip through reality in a 30-foot cone, dealing 2d6 slashing damage (DC 22 basic Reflex save). On a critical failure, creatures are also Drained 1. The composite can't use Ripping Blast again for 1d4 rounds</p>"},{"n":"Torn from the Drift","a":null,"c":"offensive","t":[],"f":"","d":"<p>While outside the Drift, the composite gains the incorporeal trait, becomes immune to precision damage, and gains resistance to all damage 10 (except force, ghost killer, or spirit; double resistance vs. non-magical).</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/wBBqKmb7hA8gLiDD":{"notes":{"per":"60 feet","speed":"(hover)"},"abilities":[{"n":"Inhuman Sounds","a":"2","c":"offensive","t":["auditory","emotion","fear","mental","visual"],"f":"","d":"<p>The electronic figment's jaw stretches downward to its chest, letting out a terrible scream. All creatures within 20 feet must succeed at a DC 20 Will save or be Frightened 2. Creatures affected by the figment's worst nightmare ability take a –2 circumstance penalty to their save.</p>"},{"n":"Worst Nightmare","a":null,"c":"offensive","t":[],"f":"","d":"<p>The electronic figment can alter its appearance to resemble creatures that have previously hurt the target, whether in combat or traumatic memories. After Striking a creature, the figment's appearance changes to the creature's worst nightmare; it gains a +2 circumstance bonus to AC and saves against its target creature.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/8mrbCW1egVL4Jg40":{"lang":["Common","Necril"],"notes":{"per":"darkvision"},"abilities":[{"n":"Crumbling Form","a":null,"c":"defensive","t":[],"f":"","d":"<p>A nuclear mummy is ionized to the point of disintegration. Once a nuclear mummy is reduced to fewer than half its Hit Points, or upon being damaged by a critical hit, it starts falling apart, reducing its Armor Class to 15.</p>"},{"n":"Ionizing Presence","a":null,"c":"defensive","t":["aura","radiation"],"f":"","d":"<p>10 feet. The nuclear mummy is highly radioactive. Any living creature that starts its turn within the emanation takes 1d6 poison damage (DC 17 basic Fortitude save).</p>"},{"n":"Siphon","a":null,"c":"offensive","t":[],"f":"","d":"<p>When an electrovore mummy scores a critical hit with a tail Strike against a living creature wielding or wearing tech gear or a creature with the tech trait, it siphons off a portion of the target's electrical energy. This restores 5 healing Hit Points to the electrovore immediately, plus 1 Hit Point per minute for the next 10 minutes; the additional healing doesn't increase if the electrovore siphons multiple times.</p>"},{"n":"Unholy Radiation","a":null,"c":"offensive","t":["disease"],"f":"","d":"<p>The nuclear mummy's touch carries a mutating radiation. An infected creature can't heal damage it takes from unholy radiation until it has been cured of the disease</p>\n<p><strong>Saving Throw</strong> DC 20 Fortitude</p>\n<p><strong>Stage 1</strong> carrier with no ill effect (1 day)</p>\n<p><strong>Stage 2</strong> 1d6 poison damage (1 day)</p>\n<p><strong>Stage 3</strong> 1d6 poison damage (1 day)</p>\n<p><strong>Stage 4</strong> 1d6 poison damage (1 day)</p>\n<p><strong>Stage 5</strong> dead, rising as a nuclear zombie (using a driftdead returned's statistics)</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/p97pGDZOIKbFxG1C":{"lang":["Petran"],"abilities":[{"n":"Fast Healing 2 (while underground)","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A monster with this ability regains the given number of Hit Points each round at the beginning of its turn.</p></p>"},{"n":"Scree Breath","a":"2","c":"offensive","t":["arcane","earth"],"f":"","d":"<p>The earth scamp breathes rocks in a 15-foot cone that deal 2d6+4 bludgeoning damage to each creature within the area (DC 19 basic Reflex save). The earth scamp can't use Scree Breath again for 1d4 rounds.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/owZo5qgtC8my1LQ7":{"lang":["Pyric"],"notes":{"per":"smoke vision"},"abilities":[{"n":"Smoke Vision","a":null,"c":"interaction","t":[],"f":"","d":"<p>The fire scamp ignores the Concealed condition from smoke.</p>"},{"n":"Fast Healing 2 (while touching fire)","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A monster with this ability regains the given number of Hit Points each round at the beginning of its turn.</p></p>"},{"n":"Flame Breath","a":"2","c":"offensive","t":["arcane","fire"],"f":"","d":"<p>The fire scamp breathes flames in a 15-foot cone that deal 2d4+4 fire damage to each creature within the area (DC 17 basic Reflex save). Creatures that fail the save also take 1d4 persistent fire damage. The fire scamp can't use Flame Breath again for 1d4 rounds.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/fu3Dex1YlMmZL8oE":{"lang":["Azlanti","Common"],"lore":[["Warfare Lore",21]],"gear":["Advanced Sihedron Guard Armor","Integrated Aeon Stone (Life-Giving)","+1 Weapon Potency Crystal (Solar Flare)","Striking Crystal (Commercial) (Solar Flare)","Gluon Crystal (Tactical) (Solar Flare)","Medpatch (Tactical)"],"notes":{"ac":"regeneration 10 (deactivated by fire)"},"abilities":[{"n":"Regeneration 10  (deactivated by fire)","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>This monster regains the listed number of Hit Points each round at the beginning of its turn. Its Dying condition never increases beyond Dying 3 as long as its regeneration is active. However, if it takes damage of a type listed in the regeneration entry, its regeneration deactivates until the end of its next turn. Deactivate the regeneration before applying any damage of a listed type, since that damage might kill the monster by bringing it to Dying 4.</p></p>"},{"n":"Punishment For Failure","a":"r","c":"defensive","t":["divine"],"f":"","d":"<p><strong>Trigger</strong> The exkruvite is reduced to 0 Hit Points. The exkruvite must use this ability when the trigger is met</p><hr><p><strong>Effect</strong> The exkruvite is utterly destroyed in a gout of green flame, leaving behind only her gear. Her soul can't be restored, and no magical means can contact her soul.</p>"},{"n":"Reactive Strike","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Aeon Flight","a":"2","c":"offensive","t":["concentrate"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p><hr><p><strong>Effect</strong> The exkruvite gains a fly Speed for 1 minute equal to her Speed.</p>"},{"n":"Battle Casting","a":"3","c":"offensive","t":[],"f":"","d":"<p>The exkruvite makes a solar shot Strike or tentacle sting Strike, then Casts a Spell requiring 2 or fewer actions against the same target. If the spell requires an attack roll, don't count the initial Strike toward her multiple attack penalty.</p>"},{"n":"Binaric Assault","a":"2","c":"offensive","t":["flourish","solarian"],"f":"","d":"<p>The exkruvite attempts a solar weapon Strike. On a success, she chooses a creature within 35 feet. She immediately teleports to any vacant square within 35 feet and attempts a solar weapon Strike on a creature within reach. If the initial Strike fails, she doesn't teleport and the action ends.</p>"},{"n":"Flicker Strike","a":"2","c":"offensive","t":["solarian","teleportation"],"f":"","d":"<p>The exkruvite attempts a melee Strike. If the attack succeeds, the exkruvite chooses a creature within 35 feet. The exkruvite immediately teleports up to 35 feet to any square within reach and attempts a melee Strike on that creature. If the initial Strike fails, the exkruvite doesn't teleport and the action ends.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/SdGlDXllojTQ80GB":{"description":"<p>A noxious, volatile gas cloud fills the air.</p>","disable":"<p>DC 20 Physical Science Lore (trained) or DC 20 Survival (trained) to filter the gas, or gust of wind or a similar spell to dispel the gas</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Volatile Ignition","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature uses an attack or ability with the fire trait</p><hr><p><strong>Effect</strong> The volatile gases ignite, dealing 4d8+14 fire damage to all creatures within a 20-foot burst centered on the triggering creature (DC 20 basic Reflex save). If the triggering creature fails its save, it catches on fire and takes 1d8 persistent fire damage.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/vtUGiHqXCVOclyYV":{"notes":{"per":"darkvision"},"abilities":[{"n":"Colony Mind","a":null,"c":"defensive","t":["aura"],"f":"","d":"<p>30 feet. All allies with colony mind within the listed range of each other are in constant telepathic communication and are aware of all threats any individual knows about. While within range of at least one ally with colony mind, when a creature rolls a success on a save against a mental effect, it gets a critical success instead.</p>"},{"n":"Smoke Sensitivity","a":null,"c":"defensive","t":[],"f":"","d":"<p>The false apari must succeed at a DC 16 Fortitude save each round it's in the presence of smoke or fall Unconscious.</p>"},{"n":"Foraging Constituents","a":"1","c":"offensive","t":[],"f":"","d":"<p>The false apari Seeks by dispersing constituents to scan a wide area, attempting to find undetected or hidden creatures within 30 feet.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/HJmS7ip59MCtwZyQ":{"lang":["Common","(Can't Speak Any Language), Master Link"],"abilities":[{"n":"Master Link","a":null,"c":"interaction","t":["arcane","mental"],"f":"","d":"<p>A homunculus can't speak, but it is telepathically linked to its creator. It can share information back and forth, including its master's knowledge and everything the homunculus hears. The range of this link is 1,500 feet. The homunculus typically has a similar attitude to its creator and is utterly faithful.</p>\n<p>If the homunculus is destroyed, the master takes 2d10 mental damage. If the master is slain, the homunculus becomes mindless, claims its current location as its lair, and instinctively attacks anyone who comes near.</p>"},{"n":"Homunculus Poison","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p>A homunculus has one dose of poison in a reservoir in its head. It can refill this poison from its reserves with an Interact action</p>\n<p><strong>Saving Throw</strong> DC 15 Fortitude</p><hr><p><strong>Maximum Duration</strong> 6 rounds</p>\n<p><strong>Stage 1</strong> 1d6 poison and Enfeebled 1 (1 round).</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/CbjxNI5Btx5XbLTX":{"abilities":[{"n":"Deep Plunge","a":"1","c":"offensive","t":[],"f":"","d":"<p>The brine shark dives straight down into the water, moving up to twice its swim Speed in a straight vertical line. It can use this ability while grabbing a creature.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/Cajy8A0lPNIqFfxS":{"lang":["Thalassic"],"notes":{"hp":"fast healing 2 (while underwater)"},"abilities":[{"n":"Fast Healing 2 (While Underwater)","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A monster with this ability regains the given number of Hit Points each round at the beginning of its turn.</p></p>"},{"n":"Acid Breath","a":"2","c":"offensive","t":["acid","arcane"],"f":"","d":"<p>The water scamp breathes acid in a 15-foot cone that deals 2d6 acid damage to each creature within the area (DC 17 basic Reflex save).</p>\n<p>The water scamp can't use Acid Breath again for 1d4 rounds.</p>"},{"n":"Drench","a":"1","c":"offensive","t":["arcane","water"],"f":"","d":"<p>The water scamp shakes out a seemingly endless supply of water from its fur to put out all fires in a 5-foot emanation. The scamp extinguishes all non-magical fires automatically and attempts to counteract magical fires (+7 counteract modifier).</p>"},{"n":"Fouled Water","a":null,"c":"offensive","t":[],"f":"","d":"<p>The fouled water from this elemental deals an additional 1d6 poison damage with its attacks (DC 14 basic Fortitude save).</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/a1sE7bci1Tv2ef8h":{"abilities":[{"n":"Giant Centipede Venom","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p><strong>Saving Throw</strong> DC 14 Fortitude</p><hr><p><strong>Maximum Duration</strong> 6 rounds</p>\n<p><strong>Stage 1</strong> 1d4 poison damage (1 round)</p>\n<p><strong>Stage 2</strong> 1d4 poison damage and Off-Guard (1 round)</p>\n<p><strong>Stage 3</strong> 1d4 poison damage, Clumsy 1, and Fatigued (1 round)</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/hnUEp4dd4rzPAPPs":{"lang":["Coshyco"],"lore":[["Farming Lore",5]],"gear":["Knife","Smoke Grenade (Commercial)","Armored Coat"],"abilities":[{"n":"Absorb Shock","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The golden coshyco would take bludgeoning damage</p><hr><p><strong>Effect</strong> The golden coshyco absorbs the shock of the blow into its flesh, avoiding broken bones or other significant damage. They gain resistance 3 to bludgeoning for the triggering attack.</p>"},{"n":"Adjust Shape","a":"2","c":"offensive","t":["manipulate"],"f":"","d":"<p>The golden coshyco rearranges their skeleton to adapt to their circumstances. They choose between squat, lanky, or flexible. If they take on the squat shape, they gain a +2 circumstance bonus to Athletics checks to Force open. If they choose lanky, they gain a +2 circumstance bonus to Acrobatics checks to Squeeze. If they choose flexible, their reach increases to 10 feet with held melee weapons.</p>"},{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>The Golden coshyco's Strikes deal 1d6 extra precision damage to Off-Guard creatures.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/6yjddYWGOaX2xNGA":{"lang":["Aklo","Common"],"notes":{"speed":"(hover)"},"abilities":[{"n":"Rudimentary Camouflage","a":null,"c":"defensive","t":[],"f":"","d":"<p>A grabzit blends in with objects in their surroundings and is always Concealed.</p>"},{"n":"Bypass Firewalls","a":"f","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The grabzit's Glitching Strikes are affecting a tech object</p><hr><p><strong>Effect</strong> The grabzit's Strikes deal additional precision damage equal to the item's glitching value to the creature holding the triggering item for 1 round.</p>"},{"n":"Glitching Strikes","a":null,"c":"offensive","t":[],"f":"","d":"<p>Whenever a grabzit targets a creature with a Strike or spell, a tech object the target is holding becomes Glitching 1 (Glitching 2 on a critical hit).</p>"},{"n":"Remote Hack","a":"1","c":"offensive","t":["concentrate","mental"],"f":"","d":"<p>The grabzit remotely hacks an item with the tech trait held or worn by a creature within 30 feet. The creature attempts a DC 20 Will save. On a failure, it takes 1d6 electricity damage and is Off-Guard for 1 round. A grabzit can also use this ability to Hack creatures with the tech trait.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/zfWzxaQJA4d7vM8k":{"description":"<p>The prism rotates rapidly, causing water to spin alongside it.</p>","disable":"<p>DC 17 Thievery to jam the rotating mechanism, or DC 19 to pull the graviton prism out of rotation</p>","routine":"<p>(1 action) The graviton prism hums as it continues to increase the rate at which it spins. All creatures within a 10-foot emanation of the prism must attempt a DC 17 basic Fortitude save. On a failure, a target is pushed back 5 feet (10 feet on a critical failure). Each subsequent time the graviton prism attempts its routine, the emanation increases by 5 feet (maximum of 25 feet).</p>","abilities":[{"n":"Gravitational Whirl","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature or object enters the area marked on the map</p><hr><p><strong>Effect</strong> The graviton prism increases the velocity of its rotation, dealing 1d12 bludgeoning damage. All creatures within 5 feet of the graviton prism must attempt a DC 17 basic Reflex save. On a failure, creatures are additionally pushed 5 feet away from the gravitational prism (10 feet on a critical failure). The graviton prism then rolls initiative.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/wSrnxi2Uw1wqGByq":{"description":"<p>A supernatural power rapidly changes the surroundings of this area to horrify the living.</p>","disable":"<p>Disable DC 26 Perception to see through the haunt or DC 30 Occultism or DC 30 Religion to banish the visions, and DC 28 Diplomacy to snap someone else out of it once you are free. Disabling only ends the haunt's effects on one creature.</p>","routine":"<p>(3 actions) The haunt rolls on the Corrupt Terrain table.</p><table><thead><tr><th><p>1d6</p></th><th><p>Results</p></th></tr></thead><tbody><tr><td><p>1</p></td><td><p>Flesh and egg-sacs crawl along the walls, and an acidic smell penetrates your nose. Living creatures must attempt a DC 20 Fortitude save, becoming sickened 1 on a failure and sickened 2 on a critical failure. This lasts until the haunt ends. (visual)</p></td></tr><tr><td><p>2</p></td><td><p>The walls morph into sharp iron spikes splattered with blood, and meat hooks dangle from the ceiling. Living creatures moving in the area take 4d8 piercing damage (DC 20 basic Reflex ). (metal)</p></td></tr><tr><td><p>3</p></td><td><p>Infinite darkness envelops you, and the sounds of something tremendously huge rumble nearby. The haunt casts a 2nd-rank darkness spell.</p></td></tr><tr><td><p>4</p></td><td><p>Plants made of flesh, bones, and nerves grow from all surfaces, crying out in the voices of agonized loved ones. Living creatures must attempt a DC 20 Will save or become frightened 1 until the haunt ends (frightened 2 on a critical failure). (auditory, emotion, mental, fear)</p></td></tr><tr><td><p>5</p></td><td><p>Everything goes white, and you feel your senses leaving you as your body goes numb. Living creatures take 4d8 cold damage (DC 20 basic Fortitude save). (visual)</p></td></tr><tr><td><p>6</p></td><td><p>You experience your worst nightmare again (as the electronic figment's ability). Living creatures take 4d8 mental damage (DC 20 basic Will save). (emotion, mental)</p></td></tr></tbody></table>","stealthNote":"<p>(expert)</p>","abilities":[{"n":"Corrupt Terrain","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature enters the area the haunt has power over</p><hr><p><strong>Effect</strong> The haunt rolls on the Corrupt Terrain table, then rolls initiative. The DC for all effects is 20.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/uAWnNaLq92Yas95U":{"lang":["shortwave (100 feet); truespeech (constant)"],"lore":[["Drift Lore",16]],"abilities":[{"n":"Save Our Souls","a":null,"c":"interaction","t":[],"f":"","d":"<p>A hestramo can sense distress signals within one light-second (approximately 186,000 miles).</p>"},{"n":"Shipbound Bypass","a":null,"c":"interaction","t":[],"f":"","d":"<p>The hestramo can move through walls, ceilings, floors, and objects in a starship as if they have the incorporeal trait.</p>"},{"n":"Shortwave","a":null,"c":"interaction","t":["tech"],"f":"","d":"<p>A hestramo can communicate wirelessly with any creatures in range if they have the shortwave ability or are a creature with the tech trait. They can attempt Computers checks to Hack and Thievery checks to Disable a Device on items with the tech trait within this range.</p>"},{"n":"Slip Drive","a":null,"c":"interaction","t":[],"f":"","d":"<p>The hestramo has an internal biomechanical Drift engine that enables them to travel freely between the Drift and other planes, as well as between two non-Drift planes. They can cast Interplanar Teleport as a 7th-rank occult innate spell at will.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/ZZ4Vz6LU2CIGiRCi":{"description":"<p>A wooden trapdoor covers a mine shaft that's 10 feet square and 60 feet deep.</p>","disable":"<p>DC 21 Thievery to remove the trapdoor</p><p>T<strong>rapdoor Hardness</strong> 3; <strong>Trapdoor HP</strong> 12 (BT 6); <strong>Immunities</strong> critical hits, object immunities, precision damage</p>","reset":"<p>Creatures can still fall into the mine shaft, but the trapdoor must be reset manually for the hazard to become hidden again.</p>","stealthNote":"<p>(or 0 if the trapdoor is disabled or broken)</p>","abilities":[{"n":"Pitfall","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature walks onto the trapdoor</p><hr><p><strong>Effect</strong> The triggering creature falls in and takes falling damage (typically 30 bludgeoning damage). That creature can use the Grab an edge reaction to avoid falling.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/q9W9OJuFV6MZrmd9":{"description":"<p>A rotating 20-foot aperture full of blades, grinders, and mashers attempts to suck anything within a 15-foot cone area in front of it into its processors.</p>","disable":"<p>DC 24 Crafting (expert) to carefully disassemble the maw's parts, DC 28 Athletics to stop the blades, or DC 26 Thievery (expert) to trip the mechanisms; two successes are required to disable the intake maw</p>","routine":"<p>(3 actions) The trap turns its 15-foot cone 45 degrees.</p>","abilities":[{"n":"Hungry Maw","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature enters the 15-foot cone area in front of the maw</p><hr><p><strong>Effect</strong> The maw draws everything within the area of effect toward its processing mechanisms and then rolls initiative. Creatures in the affected area must attempt a DC 26 Reflex save. Any creature that starts its turn within the maw itself takes 1d10+9 bludgeoning damage, 1d10+9 piercing damage, and 1d10+9 slashing damage. A creature that dies within the maw is destroyed completely, along with all of their gear.</p><hr><p><strong>Critical Success</strong> The creature is unaffected.</p>\n<p><strong>Success</strong> The creature is dragged 5 feet toward the intake maw.</p>\n<p><strong>Failure</strong> The creature is dragged 10 feet toward the maw and knocked Prone.</p>\n<p><strong>Critical Failure</strong> The creature is dragged 20 feet and pulled into the maw, knocked prone, and takes 2d10+9 bludgeoning damage.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/nsqzIXHkfdCqcs8m":{"lang":["Common","Petran","truespeech"],"gear":["Flaming Machine Gun","Hidden Soldier Armor","Projectile Ammo (120)"],"notes":{"speed":"earth glide"},"abilities":[{"n":"Earth Glide","a":null,"c":"offensive","t":[],"f":"","d":"<p>The jabali can Burrow through dirt and stone at their full burrow Speed, leaving no tunnels or signs of their passing.</p>"},{"n":"Stone Clutch","a":null,"c":"offensive","t":["arcane","earth"],"f":"","d":"<p>When the jabali Pushes a creature into a stone barrier, the surface grips it with fingers of stone. The target must succeed at a DC 22 Reflex save or become Grabbed by the surface (Escape).</p>"},{"n":"Push 10 feet","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Push in its damage entry</p><hr><p><strong>Effect</strong> The monster attempts to Shove the creature. This attempt neither applies nor counts toward the monster's multiple attack penalty. If Push lists a distance, change the distance the creature is pushed on a success to that distance.</p></p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/voJb8Ac4I2Vryb5e":{"lang":["Aklo","Common"],"gear":["Keycard"],"notes":{"speed":"(hover)"},"abilities":[{"n":"Rudimentary Camouflage","a":null,"c":"defensive","t":[],"f":"","d":"<p>A grabzit blends in with objects in their surroundings and is always Concealed.</p>"},{"n":"Bypass Firewalls","a":"f","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The grabzit's Glitching Strikes are affecting a tech object</p><hr><p><strong>Effect</strong> The grabzit's Strikes deal additional precision damage equal to the item's glitching value to the creature holding the triggering item for 1 round.</p>"},{"n":"Glitching Strikes","a":null,"c":"offensive","t":[],"f":"","d":"<p>Whenever a grabzit targets a creature with a Strike or spell, a tech object the target is holding becomes Glitching 1 (Glitching 2 on a critical hit).</p>"},{"n":"Remote Hack","a":"1","c":"offensive","t":["concentrate","mental"],"f":"","d":"<p>The grabzit remotely hacks an item with the tech trait held or worn by a creature within 30 feet. The creature attempts a DC 20 Will save. On a failure, it takes 1d6 electricity damage and is Off-Guard for 1 round. A grabzit can also use this ability to Hack creatures with the tech trait.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/935PXdJ2z80tr116":{"description":"<p>A shock grid built into the trapdoor releases a powerful electric charge.</p>","disable":"<p>DC 16 Computers (trained) to disable the trapdoor's programming, DC 17 Crafting (trained) to rewire the shock grid, or DC 18 Thievery (trained) to deactivate the shock grid</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Jolt","a":"r","c":"defensive","t":["electricity"],"f":"","d":"<p><strong>Trigger</strong> A creature grasps the trapdoor directly or with a tool</p><hr><p><strong>Effect</strong> The trap deals 5d8 electricity damage to the triggering creature and creatures within 5 feet of the triggering creature (DC 25 basic Reflex save).</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/9CqhC4cNKMKVcmw5":{"lang":["Aklo","Common"],"abilities":[{"n":"Eyespots","a":null,"c":"interaction","t":[],"f":"","d":"<p>A star tardigrade can’t see anything beyond 30 feet</p>"},{"n":"Mauler","a":null,"c":"interaction","t":[],"f":"","d":"<p>The star tardigrade gains a +2 circumstance bonus to damage rolls against creatures it has Grabbed.</p>"},{"n":"Tun State","a":"f","c":"interaction","t":[],"f":"once per week","d":"<p><strong>Trigger</strong> The tardigrade would be reduced to 0 Hit Points or die due to starvation, suffocation, or similar environmental causes</p>\n<p><strong>Frequency</strong> once per week</p>\n<p><strong>Requirements</strong> The tardigrade isn't already in Tun State</p><hr><p><strong>Effect</strong> The tardigrade doesn't die but instead remains at 1 Hit Point and curls into a dry ball, called a tun. While in this state, the tardigrade is Unconscious; doesn't need to eat, drink, or breathe; and increases its resistance to 20. It remains in Tun State indefinitely until covered in significant amounts of water, at which point it begins to rehydrate, gaining regeneration 5. The regeneration persists until the star tardigrade reaches maximum Hit Points. The tardigrade then exits its Tun State.</p>"},{"n":"Waterbear Hug","a":"2","c":"offensive","t":[],"f":"","d":"<p>The star tardigrade lunges at its prey. It Leaps up to 30 feet, attempting to Grab up to three creatures in its path.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/15npUAVmcGGy5RDk":{"lang":["Azlanti","Diabolic","Utopian","telepathy 100 feet"],"notes":{"per":"darkvision"},"abilities":[{"n":"Accept Your Fate","a":"r","c":"defensive","t":["divine"],"f":"","d":"<p><strong>Trigger</strong> A creature within 30 feet of the lesser kurshudi uses a fortune effect that allows for a reroll</p><hr><p><strong>Effect</strong> The lesser kurshudi can select which of the rolled dice is used for the result, even if the creature's ability allows it to select a rerolled result. If this effect causes a target's roll to critically fail, the lesser kurshudi becomes Quickened for 1 round.</p>"},{"n":"Machine Gun","a":null,"c":"offensive","t":["unholy"],"f":"","d":"<p>The lesser kurshudi manifests ammo for this machine gun through faith, and never needs to reload. A creature that critically fails its save against Area Fire from this machine gun also takes 1d6 persistent spirit damage.</p>"},{"n":"Spell Sanction","a":"1","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> The lesser kurshudi's last action this round was to Cast a Spell</p><hr><p><strong>Effect</strong> The lesser kurshudi chooses one target affected by the triggering spell, whether it failed its save or was hit with a spell attack. That target takes an additional 1d10 persistent mental damage, and the lesser kurshudi attempts to Demoralize it, using the triggering spell's range. This attempt to Demoralize loses the auditory trait and gains the visual trait, and the lesser kurshudi doesn't take a penalty if the target doesn't understand their language.</p>"},{"n":"War Sanction","a":"1","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> The lesser kurshudi's last action this round was to Area Fire their machine gun</p><hr><p><strong>Effect</strong> The lesser kurshudi chooses one target affected by the Area Fire that failed its save. That target takes an additional 1d10 persistent spirit damage and becomes suppressed as long as the persistent damage continues.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}],"strikeNotes":{"Area Fire":"<p>plus Suppressed</p>"}},"sf2e-anachronism.tales-from-the-vast-bestiary/oBGcMjyBZmjjy5GC":{"lang":["Azlanti","Common"],"gear":["Aeon Rifle","Baton","Tactical Aeon Guard Armor","Aeon Stone (Uplifting)","Battery (Tactical) (2)"],"abilities":[{"n":"Beast Bully","a":null,"c":"defensive","t":[],"f":"","d":"<p>Cal can use Intimidation to Make an impression on beasts and to make very simple Requests of them.</p>"},{"n":"Aeon Precision","a":"1","c":"offensive","t":["concentrate"],"f":"","d":"<p>With training and careful aim, Cal can single out a target. Until the end of his next turn, ranged aeon rifle strikes against a target deal an additional 1d10 precision damage, and reduce the circumstance bonus to AC the target might gain from cover by 1. These benefits only apply within their weapon's first range increment.</p>"},{"n":"Fly Free","a":"2","c":"offensive","t":["concentrate"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p><hr><p><strong>Effect</strong> Cal gains a fly Speed for 1 minute equal to his Speed.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/nnoHSZvglRmCABii":{"notes":{"hp":"explosion","per":"smoke vision"},"abilities":[{"n":"Smoke Vision","a":null,"c":"interaction","t":[],"f":"","d":"<p>The living wildfire ignores the Concealed condition from smoke.</p>"},{"n":"Explosion","a":null,"c":"defensive","t":["fire"],"f":"","d":"<p>When the living wildfire dies, it explodes, dealing 3d6 fire damage to each creature in a 10-foot emanation (DC 19 basic Reflex save).</p>"},{"n":"Spreading Flames","a":"1","c":"offensive","t":["fire","primal"],"f":"","d":"<p><strong>Requirements</strong> The living wildfire's last action was a Strike that dealt fire damage</p><hr><p><strong>Effect</strong> The fire flares, dealing 3d6 fire damage to each creature adjacent to that target with a DC 19 basic Reflex save.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/7TRt5gMQR2CNofyF":{"description":"<p>A beverage machine begins shuddering before spewing scalding liquid onto bystanders.</p>","disable":"<p>DC 17 Crafting or DC 17 Computers to disable the machine or DC 15 Athletics to push it over on its side</p>","reset":"<p>The beverage machine runs out of liquid after 4 rounds, and cups after 6 rounds.</p>","routine":"<p>(1 action) The beverage machine continues spewing liquid in a 15-foot cone. It then attempts a cup throw Strike at the nearest target.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Dispense Drink","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature inputs the wrong commands into the machine</p><hr><p><strong>Effect</strong> The machine expels scalding hot liquid that deals 1d6+10 fire damage to all creatures within a 15-foot cone (DC 19 basic Reflex save). It then rolls initiative.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/nRGCPmAuogfp7Ub3":{"description":"<p>The irrigation system pumps water irregularly, flooding some fields and draining all of the water out of others. The electrical systems that keep things in check have gone haywire, resulting in arcs of electricity.</p>","disable":"<p>DC 17 Computers (trained) or Thievery (trained) to enter the correct shutdown sequence on the control panel and disable the irrigator, or DC 20 Crafting (trained) or Farming Lore (trained) to repair the irrigator</p>","reset":"<p>The Guiding Intelligence can reset the trap 24 hours later.</p>","routine":"<p>(4 actions) The irrigator Irrigates as many targets as possible, then follows up with a zap or spigot Strike. The irrigator prioritizes targeting creatures attempting to disable or repair it.</p>","abilities":[{"n":"System Overload","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The Guiding Intelligence activates the hazard</p><hr><p><strong>Effect</strong> The irrigation system begins to malfunction, releasing a pulse of disrupting static. Creatures within 100 feet must attempt a DC 18 Fortitude save. On a failure, tech items in a creature's possession become Glitching 1, and if the creature has the tech trait, they become glitching 1. Then, the irrigator rolls initiative.</p>"},{"n":"Irrigate","a":"2","c":"offensive","t":[],"f":"","d":"<p>The irrigator sprays pressurized water in a 20-foot cone. All creatures in the area take 1d10+6 bludgeoning damage (DC 18 basic Reflex save). On a failure, a creature is also Suppressed.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/sQcL1BxWO8pDL32e":{"abilities":[{"n":"Reactive Strike","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Maul","a":"3","c":"offensive","t":[],"f":"","d":"<p>The mature moon bear makes two claw Strikes against the same target. If both Strikes hit, the target is knocked Prone.</p>"},{"n":"Parental Protector","a":null,"c":"offensive","t":[],"f":"","d":"<p>A mature moon bear deals an additional 4 damage to any creature threatening one of her cubs.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/RdEGNBFPFuXaUeQJ":{"abilities":[{"n":"Frenzy Feed","a":null,"c":"defensive","t":[],"f":"","d":"<p>The mechanolocust swarm must consume organic material. If they're not actively sharing space with and eating organic material, they must Stride until they are.</p>"},{"n":"Sleep Mode","a":null,"c":"defensive","t":[],"f":"","d":"<p>Mechanolocusts can enter a dormant state, appearing dead and without electrical impulse. When in this state, their Stealth modifier is +20.</p>"},{"n":"Swarming Bites","a":"1","c":"offensive","t":[],"f":"","d":"<p>Each enemy in the swarm's space takes 2d10+5 piercing damage with a DC 21 basic Reflex save. A creature that fails its save is also Sickened 2 until the start of the swarm's next turn.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/T7AFTkLqUWshU1cE":{"description":"<p>An asteroid hurtles toward Moondrop Springs, surrounded by a collection of smaller, flaming projectiles.</p>","disable":"<p>DC 24 Acrobatics (trained) or Piloting (trained) to dodge incoming meteors, or DC 28 Nature (trained) or DC 28 Religion (trained) to invoke primal or divine protection from meteoric destruction</p>","reset":"<p>The trap deactivates and resets after 3 rounds.</p>","routine":"<p>(3 actions) The trap makes three meteor Strikes against creatures or structures.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Shower","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The Guiding Intelligence activates the hazard</p><hr><p><strong>Effect</strong> An asteroid collides with a random structure in town, dealing 1d10 bludgeoning damage. The hazard then rolls initiative.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/ynIk8SHVRjC2NdTz":{"lang":["Castrovelian","Common","Necril"],"lore":[["Moonside-250 Lore",20]],"notes":{"per":"cameravision, darkvision 120 feet","speed":"(hover)"},"abilities":[{"n":"Cameravision","a":null,"c":"interaction","t":[],"f":"","d":"<p>Missy Moon can see through every camera on Moonside-250, as Clairvoyance.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Digital Domination","a":"2","c":"offensive","t":["occult"],"f":"","d":"<p>Missy Moon can hack into any computer on Moonside-250 as if using the control machine spell. Missy Moon can control only one computer at a time. Computers controlled by Missy Moon can expose creatures to the Moonside Watcher haunt.</p>"},{"n":"Flicker Out","a":"1","c":"offensive","t":["illusion","occult"],"f":"","d":"<p>Missy Moon dims like an extinguished neon light, becoming invisible until the beginning of her next turn.</p>"},{"n":"I, Moonside","a":"1","c":"offensive","t":["concentrate","occult"],"f":"","d":"<p>Missy Moon focuses on how she and Moonside-250 are one, allowing parts of herself to manifest from the floor, the walls, and the ceiling. For 1d4 rounds, Missy Moon can attempt ghostly touch Strikes with a reach of 120 feet or cast spells from any point within 120 feet.</p>"},{"n":"Jumpscare","a":"r","c":"offensive","t":["emotion","mental","move","occult"],"f":"","d":"<p><strong>Requirements</strong> Missy Moon's turn begins, and she was invisible</p><hr><p><strong>Effect</strong> Missy Moon reappears, screaming in the face of a living creature. She Strides up to her Speed and attempts to Demoralize a creature she is adjacent to.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/P1qqKvHeBahnY6dd":{"description":"<p>Three Missy Moon mannequins spring to life, animated by a supernatural force.</p>","disable":"<p>DC 18 Thievery (trained) three times to unlock the doors or DC 22 Religion (trained) to exorcise a spirit from one mannequin</p>","reset":"<p>The mannequins freeze in place as soon as there is no life within the room, resetting the haunt.</p>","routine":"<p>(9 actions) Each of the mannequins uses three of the haunt's actions on each turn, and the haunt loses three actions each turn for every disabled or destroyed mannequin. Each mannequin uses its first action to Stride up to 15 feet and spends its remaining two actions making mannequin fist or flung trinket Strikes. Each mannequin has its own separate multiple attack penalty.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Awaken","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature tries to remove any items from area <strong>B15</strong></p><hr><p><strong>Effect</strong> The door to the room locks, and the mannequins all lurch toward the triggering creature, Striding up to 15 feet, then roll initiative.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/pyvr9GOYkdQ1ZiAH":{"abilities":[{"n":"Strange Light","a":null,"c":"defensive","t":["aura","light"],"f":"","d":"<p>15 feet. A mosaic soul glows with a colored light, casting dim light in the emanation.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Disorganized Emotions","a":null,"c":"offensive","t":[],"f":"","d":"<p>When a mosaic soul fails a saving throw against an emotion effect, a single solid hue takes over its form, and it loses the incorporeal trait for 1d4 rounds. During this time, the mosaic soul can't use Swirling Colors, and its strange light aura is disabled.</p>"},{"n":"Mosaic Touch","a":null,"c":"offensive","t":[],"f":"","d":"<p>The soul's touch Strike unravels living targets into their components, leaving grievous wounds like acid burns. A living creature that takes Hit Point damage from the mosaic soul's touch Strike and must attempt a DC 17 Fortitude save or take 2d6 persistent acid damage.</p>"},{"n":"Swirling Colors","a":"2","c":"offensive","t":["light","visual"],"f":"","d":"<p>The mosaic soul's colors shimmer and invert in terrible flashes. All other creatures within a 30-foot emanation must attempt a DC 19 Fortitude save (mosaic souls are immune to this ability). The mosaic soul's strange light aura casts bright light until the start of its next turn.</p><hr><p><strong>Critical Success</strong> The creature is unaffected.</p>\n<p><strong>Success</strong> The creature is Dazzled until the end of its next turn.</p>\n<p><strong>Failure</strong> The creature is Blinded until the end of its next turn.</p>\n<p><strong>Critical Failure</strong> The creature is blinded until the end of its next turn and Fascinated for 1 minute.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/qqn4KTi4pJOXS1iE":{"abilities":[{"n":"Reactive Strike","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Flyby Flurry","a":"2","c":"offensive","t":[],"f":"","d":"<p>The braantu flies up to its Speed in a line and makes a wing spur Strike against up to three creatures in the line. If the Strike hits, the creature takes damage and is off-guard until the beginning of the braantu's next turn.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/6mIEX8En6mXcSfYe":{"lang":["Common"],"gear":["Advanced Abadarcorp Travel Suit (with Missy Moon logo)","Credstick"],"abilities":[{"n":"Corporate Promises","a":"1","c":"offensive","t":["auditory","concentrate","mental"],"f":"","d":"<p>Narzor uses misleading flattery and dishonest wording to trick his employees into doing his bidding in exchange for promotions, better food, or improved quality of life aboard the way station. One employee within 15 feet Steps, Strides, Strikes or Grapples as a reaction.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/0Y1m7suv1XMXh3wP":{"lang":["Common","Necril"],"abilities":[{"n":"Crumbling Form","a":null,"c":"defensive","t":[],"f":"","d":"<p>A nuclear mummy is ionized to the point of disintegration. Once a nuclear mummy is reduced to fewer than half its Hit Points, or upon being damaged by a critical hit, it starts falling apart, reducing its Armor Class to 15.</p>"},{"n":"Ionizing Presence","a":null,"c":"defensive","t":["aura","radiation"],"f":"","d":"<p>10 feet. The nuclear mummy is highly radioactive. Any living creature that starts its turn within the emanation takes 1d6 poison damage (DC 17 basic Fortitude save).</p>"},{"n":"Unholy Radiation","a":null,"c":"offensive","t":["disease"],"f":"","d":"<p>The nuclear mummy's touch carries a mutating radiation. An infected creature can't heal damage it takes from unholy radiation until it has been cured of the disease</p>\n<p><strong>Saving Throw</strong> DC 20 Fortitude</p>\n<p><strong>Stage 1</strong> carrier with no ill effect (1 day)</p>\n<p><strong>Stage 2</strong> 1d6 poison damage (1 day)</p>\n<p><strong>Stage 3</strong> 1d6 poison damage (1 day)</p>\n<p><strong>Stage 4</strong> 1d6 poison damage (1 day)</p>\n<p><strong>Stage 5</strong> dead, rising as a nuclear zombie (using a driftdead returned's statistics)</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/pwMBy4djQ789fm6C":{"description":"<p>With each rotation of the pyramid, energy collects in the crater beneath it.</p>","disable":"<p>DC 14 Religion to counteract the daemonic energy or DC 17 Thievery to stop the pyramid's movement</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Drowning Air","a":"r","c":"defensive","t":["divine"],"f":"","d":"<p><strong>Trigger</strong> A creature moves into a space underneath the pyramid</p><hr><p><strong>Effect</strong> The triggering creature feels its lungs fill with water, despite being in air. They take 2d6+5 void damage (DC 17 basic Fortitude save). On a critical failure, the target becomes Drained 1 for 1 day.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/eEeA6VFeu4JPbkhP":{"description":"<p>The deep red skin of these melon-sized berries strain to contain the syrupy juice and fermentation gases within</p>","disable":"<p>DC 14 Nature to carefully prune the stalks without disturbing the fruit, or DC 17 Life science lore or DC 17 Thievery to detonate the overripe fruit from a safe distance</p>","abilities":[{"n":"Explosive Fermentation","a":"r","c":"defensive","t":["inhaled","poison"],"f":"","d":"<p><strong>Trigger</strong> A creature touches the overripe fruit stalk</p><hr><p><strong>Effect</strong> The fruit explodes in a spray of liquid that affects all creatures in a 10-foot emanation. Breathing in the liquid deals 2d8+3 poison damage (DC 17 basic Fortitude save). On a critical failure, a creature is Clumsy 1 for 1 minute.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/pFZVdP2BxdIZp9Ii":{"description":"<p>The memories of frequent medical care for the dying influence two PCs to repeat the past.</p>","disable":"<p>DC 30 Occultism or DC 30 Religion to banish the spirits, DC 26 Athletics to physically shake a creature into consciousness, or DC 24 Medicine to treat a creature's dissociative symptoms.</p>","reset":"<p>The haunt resets after 1 day unless the grief of the patient and doctor are dealt with.</p>","routine":"<p>(3 actions) If there are fewer than two creatures under the haunt's effect, it selects a new target to replace a missing patient or doctor; the target must attempt a DC 26 Will save. On the doctor's turn, they step forward and begin applying medical care to the patient. The doctor attempts a DC 25 Medicine check. Afterward, they can attempt a new Will save to escape the haunt.</p><hr><p><strong>Critical Success</strong> The doctor does not harm the patient.</p><p><strong>Success</strong> The doctor deals 1d8+4 poison damage, 1d8+4 piercing damage or 1d8+4 slashing damage to the target (chosen at random).</p><p><strong>Failure</strong> As success, but the doctor deals 2d8+9 poison damage, 2d8+9 piercing damage or 2d8+9 slashing damage</p><p><strong>Critical Failure</strong> As success, but the doctor deals 4d8+18 poison damage, 4d8+18 piercing damage or 4d8+18 slashing damage.</p>","stealthNote":"<p>(expert)</p>","abilities":[{"n":"Zone Out","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Two creatures enter area <strong>C7</strong></p><hr><p><strong>Effect</strong> The creatures must succeed at a DC 26 Will save or become controlled, performing someone else's medical routine on autopilot. One creature is designated the doctor, one is designated the patient. The patient Strides 15 feet toward a bed within the haunt and then lies down. The haunt then rolls initiative, though it isn't obvious that a haunt is influencing them. Creatures that fail their save against the haunt are immune for 24 hours. The haunt can only affect two creatures at a time.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/gkF1d4L2HsCQGWoe":{"description":"<p>Noxious fog settles over the town, choking the senses with acrid fumes.</p>","disable":"<p>DC 23 Chemistry lore (trained) or DC 23 Life science lore (trained) to denature the poison, DC 20 Survival (trained) to prevent inhalation, or air bubble or a similar spell to protect a creature from the poison</p>","reset":"<p>The trap deactivates and resets after 3 rounds.</p>","routine":"<p>(1 action) The poisonous fog deals 2d8 poison damage to all creatures (DC 19 basic Fortitude save)</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Noxious Fumes","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The Guiding Intelligence activates the hazard</p><hr><p><strong>Effect</strong> Noxious gas fills the air throughout Moondrop Springs. All creatures must attempt a DC 19 Fortitude save, becoming Sickened 2 for 1 minute on a failure. The poison fog rolls initiative.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/itkbvvYqMxaURlTo":{"abilities":[{"n":"Low Gravity Kick","a":"2","c":"offensive","t":["attack"],"f":"","d":"<p>The powder beetle attempts an Athletics vs. Fortitude DC check against an adjacent creature's Fortitude DC. On a success, the beetle pushes the target 5 feet away (10 feet on a critical success). In low gravity, the target moves double the distance away and is pushed half the distance moved into the air during the movement (falling deals damage as normal).</p>"},{"n":"Rock Boring","a":null,"c":"offensive","t":[],"f":"","d":"<p>Powder beetles can burrow through stone as though it were soil.</p>"},{"n":"Stone Powder Cloud","a":"2","c":"offensive","t":[],"f":"","d":"<p>The beetle shakes its wings to create a cloud of stone powder. It gains concealment until the start of its next turn. Adjacent creatures must succeed at a DC 12 Fortitude save or become Clumsy 1 for 1 round. It can't use this ability again until it Burrows through stone.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/nID7bQHIDxI9HSQu":{"lang":["Azlanti","Common"],"abilities":[{"n":"Vitality Network","a":null,"c":"defensive","t":[],"f":"","d":"<p>A priest of Lissala has a network of vitality they can channel up to 4 bonded allies as though they were a mystic. This network can store a maximum of 20 healing Hit Points and is full at the start of combat.</p>"},{"n":"Fill Vitality","a":"1","c":"offensive","t":[],"f":"once per round","d":"<p><strong>Frequency</strong> one per round</p><hr><p><strong>Effect</strong> The priest of Lissala restores 6 Hit Pints to their vitality network, up to its maximum.</p>"},{"n":"Transfer Vitality","a":"1","c":"offensive","t":[],"f":"","d":"<p>The priest of Lissala transfers any number of Hit Points from its vitality network to a visible bonded target.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/giwJnQ0UWUp3xX2D":{"description":"<p>A colorful fungus releases psychotropic spores when a creature comes near.</p>","disable":"<p>DC 20 Nature (trained) to force the fungus into a dormant state, or DC 22 Survival (trained) to safely remove the fungus</p>","stealthNote":"<p>(trained)</p>"},"sf2e-anachronism.tales-from-the-vast-bestiary/Yw2gCuFQ65YTqWpW":{"description":"<p>A series of earthquakes begin to split the ground across the vault. Magma seeps up from the cracks, reshaping the landscape and scorching the earth.</p>","disable":"<p>DC 22 Acrobatics (trained) to avoid the burning cracks</p>","reset":"<p>The pyroclastic flow deactivates and resets after 3 rounds.</p>","routine":"<p>(3 actions) The pyroclastic flow makes lava spray Strikes against three buildings or creatures.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Earthquake","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The Guiding Intelligence activates the hazard</p><hr><p><strong>Effect</strong> The ground shakes; creatures must succeed at a DC 19 Reflex save or be knocked prone and take 1d8 fire damage. The pyroclastic flow rolls initiative.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/4TVXA3DkwKlKGO6r":{"lang":["Talican","can't speak any language"],"notes":{"per":"darkvision"},"abilities":[{"n":"Feed on Radiation","a":null,"c":"offensive","t":[],"f":"","d":"<p>While exposed to mild radiation, a radiation crawler gains fast healing 2. In severe radiation, this increases to fast healing 5; in extreme radiation, it becomes regeneration 10; and in incredible radiation, the radiation crawler is additionally Quickened.</p>"},{"n":"Radiation Poisoning","a":null,"c":"offensive","t":[],"f":"","d":"<p>If a radiation crawler critically strikes a creature with its nuclear slam Strike, the creature must attempt a DC 19 Fortitude save or be subject to the effects of a 3rd-rank irradiate spell. In areas of higher radiation, the spell heightens to match the level of local radiation.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/F2umEZocwH3eet6N":{"description":"<p>A mechanized turret pops up on intruders when they enter into range.</p>","disable":"<p>DC 30 Computers (trained) to reprogram the turret, or DC 23 Crafting (trained) to jam the sensor</p>","reset":"<p>The trap resets after 1 minute.</p>","routine":"<p>(3 actions) The trap makes a rail gun Strike against up to three creatures in range, or multiple Strikes against one creature in range if it has no additional targets.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Open Fire","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature moves within 60 feet of the turret</p><hr><p><strong>Effect</strong> The turret makes a rail gun Strike against the creature. The trap then rolls initiative.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/MKHVwq9GpBs5cHgG":{"description":"<p>Howling winds tear across the valley, uprooting trees and ripping roofs off buildings.</p>","disable":"<p>DC 19 Nature (trained) or Survival (trained) to take shelter, or DC 23 Fortitude save to endure the Gust</p>","reset":"<p>The windstorm deactivates and resets after 3 rounds.</p>","routine":"<p>(1 action) The windstorm gusts, dealing 2d8+9 bludgeoning damage to all creatures and structures in the town.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Gust","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The Guiding Intelligence activates the hazard</p><hr><p><strong>Effect</strong> The windstorm deals 1d8 bludgeoning damage to all creatures and structures. The windstorm rolls initiative.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/nNyEL8vL8QnTfMir":{"description":"<p>Scrolls and logbooks flutter open with lingering magic energy, as though they're trying to sense nearby life.</p>","disable":"<p>DC 15 Thievery to catch the scrolls, or DC 18 Religion to negate the lingering magic</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Consume Reader","a":"r","c":"defensive","t":["void"],"f":"","d":"<p><strong>Trigger</strong> A creature opens a desk in area <strong>I6</strong></p><hr><p><strong>Effect</strong> The scrolls and books within the desk fly out of the drawers and wrap around the triggering creature. The target takes 2d10+7 void damage and must attempt a basic DC 18 Fortitude save. On a critical failure, the target becomes Drained 1 as the files consume the target's essence.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/CmwfvxFCmr7Ga3Eo":{"description":"<p>A hardlight barrier forms an unnatural cube of glowing blue static that surrounds a computer console.</p>","disable":"<p>DC 23 Thievery (trained) to disable the barrier, DC 24 Computers (trained) to Hack the barrier, or Dispel Magic (4th rank; counteract DC 21) to counteract the barrier</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Forbid Entry","a":"r","c":"defensive","t":["arcane"],"f":"","d":"<p><strong>Trigger</strong> A creature attempts to pass through the barrier or touches it</p><hr><p><strong>Effect</strong> The barrier shunts the creature away, making a barrier Strike against the triggering creature.</p>"}],"strikeNotes":{"Barrier":"<p>plus the target is pushed back 5 feet (10 feet on a critical hit). The barrier takes a –2 circumstance penalty to hit if the triggering creature Stepped into the barrier or was moved by a forced movement effect.</p>"}},"sf2e-anachronism.tales-from-the-vast-bestiary/kabFp93xYWDy0jGe":{"lang":["Common","Vesk"],"abilities":[{"n":"Let Us Serve You!","a":"1","c":"offensive","t":["manipulate"],"f":"","d":"<p><strong>Requirements</strong> The retail employee has a creature Grabbed</p><hr><p><strong>Effect</strong> The employee waves greasy food in front of the creature's face, trying to sell it to them. The creature must succeed at a DC 15 Fortitude save or become Sickened 1 on a failure (Sickened 2 on a critical failure). The effect lasts for 1 minute.</p>"},{"n":"Quick Kidnapper","a":null,"c":"offensive","t":[],"f":"","d":"<p>The retail employee can move at half their regular Speed while grappling a creature.</p>"},{"n":"Slurred Slogans","a":"1","c":"offensive","t":[],"f":"","d":"<p>The retail employee mumbles out buzzwords about great deals Moonside-250 has to offer (or, occasionally, they sing \"Stay Here Forever\"). They attempt a Diplomacy check to Demoralize a creature that can hear them.</p>"},{"n":"Your Total Is…","a":"1","c":"offensive","t":["manipulate"],"f":"","d":"<p><strong>Requirements</strong> The retail employee has a creature's credstick</p><hr><p><strong>Effect</strong> The employee transfers 1d100 credits to their own credstick, charging the creature for their services. The creature must succeed at a DC 15 Will save or become Fascinated with retrieving their credstick for 1 round (2 rounds on a critical failure). If the creature does not have sufficient credits, the employee has a +2 circumstance bonus to Strikes against the creature for 1 minute.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/Bxj8boIi8TKxn9hQ":{"lang":["Common"],"abilities":[{"n":"Permaburnout","a":null,"c":"defensive","t":["aura"],"f":"","d":"<p>15 feet</p>\n<p><strong>Requirements</strong> The retail phantasm is not currently possessing a creature</p><hr><p><strong>Effect</strong> While the retail phantasm isn't possessing a creature, it resembles a glowing ball of slime emitting waves of work-related stress. All creatures that start their turns within the emanation take 1d8 spirit damage (DC 16 basic Will save). On a critical failure, the creature is also Clumsy 1 as long as it remains in the aura.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Possess Creature","a":"2","c":"offensive","t":[],"f":"","d":"<p>The retail phantasm attempts to possess an adjacent corporeal creature. This has the same effect as the Possession spell (DC 18), except the duration is 1d4 hours, and since the retail phantasm doesn't have a physical body, it's unaffected by that restriction of the spell. If the target is an employee of the same company as the retail phantasm, the DC is 22.</p>"},{"n":"Unpaid Overtime","a":"2","c":"offensive","t":["curse","divine"],"f":"","d":"<p>The retail phantasm touches an adjacent creature, causing the weight of years of toil to overcome them at once. The creature must attempt a DC 18 Fortitude save.</p><hr><p><strong>Critical Success</strong> The target is unaffected.</p>\n<p><strong>Success</strong> The target is Enfeebled 1 for 1 round.</p>\n<p><strong>Failure</strong> The target is enfeebled 1 for 24 hours and Fatigued.</p>\n<p><strong>Critical Failure</strong> The target is enfeebled 1 for 24 hours, fatigued, and falls Unconscious. If it's still unconscious after 1 minute, it wakes up automatically.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/yA1v9qJMw0JzQ1GM":{"abilities":[{"n":"Reactive Strike","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Flyby Flurry","a":"2","c":"offensive","t":[],"f":"","d":"<p>The braantu flies up to its Speed in a line and makes a wing spur Strike against up to three creatures in the line. If the Strike hits, the creature takes damage and is off-guard until the beginning of the braantu's next turn.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/nJ4G7oMV4MTsm6iA":{"description":"<p>Magical runes are etched into this flank's exposed metal frame.</p>","disable":"<p>DC 25 Arcana (trained), DC 25 Occultism (trained), DC 25 Religion (trained), or DC 33 Thievery (expert) to decipher the inherit logic of spells programmed into the machine and disable this part of the assembler</p>","abilities":[{"n":"Entropic Instability","a":"r","c":"defensive","t":["acid"],"f":"","d":"<p><strong>Trigger</strong> A creature touches the runes or critically fails a check to disable them</p><hr><p><strong>Effect</strong> The trap creates a 20-foot burst centered on the triggering creature that deals 4d10+26 acid damage (DC 25 basic Fortitude save).</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/DY9tPOD2TS9hhpMP":{"description":"<p>Exposed wires and circuitry nestle like coiled snakes among moving gears and pistons.</p>","disable":"<p>DC 33 Athletics (trained), DC 27 Crafting (expert), or DC 29 Thievery (expert) to disable this part of the assembler</p>","abilities":[{"n":"Shock and Awe","a":"r","c":"defensive","t":["electricity"],"f":"","d":"<p><strong>Trigger</strong> A creature touches the wiring or critically fails a check to disable it</p><hr><p><strong>Effect</strong> The wiring deals 4d10+26 electricity damage to the triggering creature and creatures within 5 feet (DC 25 basic Reflex save).</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/o6BRws8Ctrm2ExkL":{"gear":["Aeon Rifle","Battleglove","Advanced Sihedron Guard Armor","Aeon Stone (Life-Giving)","Battery (Tactical) (2)"],"notes":{"per":"darkvision"},"abilities":[{"n":"Punishment for Failure","a":"r","c":"defensive","t":["divine"],"f":"","d":"<p><strong>Trigger</strong> The Sihedron commander is reduced to 0 Hit Points and has used their Reward of Obedience reaction in the last year. The Sihedron commander must use this ability when the trigger is met</p><hr><p><strong>Effect</strong> The Sihedron commander is utterly destroyed, leaving behind only their equipment. Their soul can't be restored, and no magical means can contact their soul.</p>"},{"n":"Reward of Obedience","a":"r","c":"defensive","t":["divine"],"f":"once per year","d":"<p><strong>Frequency</strong> once per year</p>\n<p><strong>Trigger</strong> The Sihedron commander is reduced to 0 Hit Points but not from an effect that leaves no remains (like promession)</p><hr><p><strong>Effect</strong> The Sihedron commander restores 6d6 healing Hit Points and doesn't fall Prone or drop their equipment.</p>"},{"n":"Aeon Flight","a":"2","c":"offensive","t":["concentrate"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p><hr><p><strong>Effect</strong> The Sihedron commander gains a fly Speed for 1 minute equal to their Speed.</p>"},{"n":"Battle Casting","a":"3","c":"offensive","t":[],"f":"","d":"<p>The Sihedron commander attempts a ranged Strike with their aeon rifle or a melee Strike with their battleglove, then Casts a Spell requiring 2 actions or fewer against the same target. If the spell requires an attack roll, don't count the ranged Strike toward their multiple attack penalty.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/MhoZ5bFnRevAXGg9":{"lang":["Azlanti","(can’t speak)"],"abilities":[{"n":"Self-Destruct","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The Sihedron drone is reduced to 0 Hit Points</p><hr><p><strong>Effect</strong> The drone emits a metallic screech followed by a steady ticking sound. On its next turn, the Sihedron drone flies up to 30 feet toward the nearest foe and explodes, dealing 3d6 piercing damage in a 5-foot radius (DC 18 basic Reflex save). Its integrated aeon stone is destroyed, along with any information the drone recorded. An adjacent creature can stop the self-destruct sequence by succeeding at a DC 18 Crafting or DC 18 Thievery check to Disable a Device.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/HLK1fibTZvpf2IJ7":{"lang":["Azlanti","Common"],"gear":["Flash Grenade (Advanced) (2)","Aeon Rifle","Battleglove","Advanced Sihedron Guard Armor","Aeon Stone (Life-Giving)","Battery (Tactical) (2)"],"notes":{"per":"darkvision"},"abilities":[{"n":"Aeon Precision","a":"1","c":"offensive","t":["manipulate"],"f":"","d":"<p>The Sihedron enforcer activates their aeon rifle's experimental seeker mode. Until the end of their next turn, the Sihedron enforcer's aeon rifle Strikes deal an additional 1d10 precision damage and reduce the circumstance bonus to AC that targets gain from cover by 1. These benefits only apply within the weapon's first range increment.</p>"}],"strikeNotes":{"Flash Grenade":"<p><strong>Effect</strong> Dazzled 2 rounds (DC 22 Fortitude save)</p>"}},"sf2e-anachronism.tales-from-the-vast-bestiary/0lMVLGU0Pygh1V8Z":{"lang":["Azlanti","Common"],"gear":["Aeon Rifle","Tactical Sihedron Guard Armor","Aeon Stone (Life-Giving)","Battery (Tactical) (2)"],"abilities":[{"n":"Aeon Pulse","a":"2","c":"offensive","t":[],"f":"","d":"<p>The Sihedron surveyor releases a magitech pulse that disrupts nearby tech. All creatures within a 20-foot emanation must attempt a DC 24 Fortitude save. The Sihedron surveyor can't use Aeon Pulse again for 1d4 rounds.</p><hr><p><strong>Critical Success</strong> The creature is unaffected.</p>\n<p><strong>Success</strong> Creatures and items with the tech trait are glitching 1.</p>\n<p><strong>Failure</strong> Creatures and items with the tech trait are glitching 3.</p>\n<p><strong>Critical Failure</strong> As failure, but creatures with the tech trait are also slowed 1.</p>"},{"n":"Aeon Reload","a":"f","c":"offensive","t":[],"f":"","d":"<p>The Sihedron surveyor's magitech exocortex reloads their aeon rifle as a free action.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/KtuPyrJnRwLWHupR":{"description":"<p>A deluge of ice, snow, and sleet swirls with the howling wind.</p>","disable":"<p>DC 18 Nature or DC 18 Survival (trained) to find shelter; DC 20 Crafting (trained) or DC 20 Engineering Lore (trained) to create shelter; DC 22 Acrobatics (trained), DC 22 Athletics (trained), or DC 22 Nature (trained) to quickly carry plants and animals inside</p>","reset":"<p>The blizzard lasts for 10 rounds, then subsides to a snowstorm.</p>","routine":"<p>(1 action) The blizzard swirls. Creatures trapped in the blizzard are Blinded, Suppressed, and take 2d8+7 cold damage each round (DC 18 basic Fortitude save).</p>","abilities":[{"n":"Let It Snow","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The Guiding Intelligence activates the blizzard module</p><hr><p><strong>Effect</strong> The wind begins howling and snow swirls in every direction, creating a whiteout. The blizzard rolls initiative.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/ow7llyCYWgmaj5nh":{"notes":{"per":"darkvision"},"abilities":[{"n":"Fly-By Thief","a":"2","c":"offensive","t":["traversal"],"f":"","d":"<p>A clever scavenger, the skreechree Flies twice. At any point in this movement, it can attempt to Steal from a creature that it's adjacent to.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/EOXPrb2UlPgEKhLU":{"gear":["Shooting Starknife","Medpatch (Tactical)"],"abilities":[{"n":"Sentinel Training","a":null,"c":"interaction","t":[],"f":"","d":"<p>All Stillward sentinels are trained to communicate silently using signed Coshyco. A Stillward sentinel gains a +1 circumstance bonus to AC while adjacent to an ally.</p>"},{"n":"Reactive Strike","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Sentinel's Strike","a":"2","c":"offensive","t":[],"f":"","d":"<p>The Stillward sentinel attempts a ranged Strike aimed at a creature's limbs or other means of propulsion.</p><hr><p><strong>Critical Success</strong> The target takes damage and is Slowed 1.</p>\n<p><strong>Success</strong> The target takes damage and is Off-Guard for 1 minute.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/r6ioZdV3XyUrDjYO":{"description":"<p>Water fills deep pits in the thick clay that surrounds a forest pond, creating sticky, smelly mud.</p>","disable":"<p>DC 18 Nature or DC 18 Survival to find a safe path through the mud, or DC 20 Acrobatics or DC 20 Athletics to pull yourself or another creature free</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Grasp","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature steps into any square adjacent to a pond in Calthorn Woods</p><hr><p><strong>Effect</strong> The creature sinks into the sucking mud up to its knees. The creature is Immobilized.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/zgpAzncGlCaDx6UF":{"description":"<p>The essence of suffering appears in this room as a miasma that attempts to drown those that have escaped pain.</p>","disable":"<p>DC 15 Occultism (trained) or DC 15 Religion (trained) to soothe the suffering spirits, or DC 18 Nature to disperse the miasma with a gust of wind.</p>","routine":"<p>(1 action) The miasma attempts to suffocate all living creatures in area <strong>I8</strong> not currently suffering from an affliction or detrimental condition. Targets must attempt a DC 18 Fortitude save. On a failure, the target begins suffocating.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Miasma Swell","a":"r","c":"defensive","t":["emotion"],"f":"","d":"<p><strong>Trigger</strong> A living creature that is not currently suffering from an affliction or detrimental condition enters area <strong>I8</strong></p><hr><p><strong>Effect</strong> The miasma attempts to fill the lungs of those who don't suffer. All triggering creatures take 2d12 mental damage (DC 18 basic Will save), then the haunt rolls initiative.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/PFQ8Xa1wQLedLOob":{"lang":["Coshyco"],"gear":["Fangblade","Semi-Auto Pistol","Armored Coat","Projectile Ammo (20)"],"abilities":[{"n":"Absorb Shock","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Sursurn would take bludgeoning damage</p><hr><p><strong>Effect</strong> The coshyco absorbs the shock of the blow into its flesh, avoiding broken bones or other significant damage. They gain resistance 5 to bludgeoning for the triggering attack.</p>"},{"n":"Adjust Shape","a":"2","c":"offensive","t":["manipulate"],"f":"","d":"<p>Susrsurn rearranges their skeleton to adapt to their circumstances. They choose between squat, lanky, or flexible. If they take on the squat shape, they gain a +2 circumstance bonus to Athletics checks to Force open. If they choose lanky, they gain a +2 circumstance bonus to Acrobatics checks to Squeeze. If they choose flexible, their reach increases to 10 feet with held melee weapons.</p>"},{"n":"Leap and Load","a":"1","c":"offensive","t":["attack","move"],"f":"","d":"<p>Sursurn Leaps. At the end of her movement, she attempts a ranged Strike, then Reloads.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/yAehKdf6VbisiXM6":{"lang":["Common","Necril","(can’t speak any languages)"],"notes":{"per":"vibrovision"},"abilities":[{"n":"Vibrovision","a":null,"c":"interaction","t":[],"f":"","d":"<p>The Harvest's scanners make it excellent at pinpointing targets. It ignores the Concealed condition.</p>"},{"n":"Musical Jingle","a":null,"c":"defensive","t":["auditory","aura"],"f":"","d":"<p>The Harvest plays cheerful music wherever it goes. All creatures within a 60-foot emanation gain a +1 circumstance bonus to Perception checks against the Harvest. The Harvest can turn the music off as a single action; this gives it a +4 circumstance bonus to Stealth.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Ceiling Drop","a":"1","c":"offensive","t":["attack"],"f":"","d":"<p><strong>Requirements</strong> The Harvest is on a ceiling or wall</p><hr><p><strong>Effect</strong> The Harvest shrieks and drops onto creatures below it. It Leaps. Any creature within its space when it lands must succeed at a DC 26 Reflex save or take 5d6 bludgeoning damage. Creatures that critically fail their save are knocked Prone.</p>"},{"n":"Chase Sequence","a":"2","c":"offensive","t":["attack","move"],"f":"","d":"<p>The Harvest Strides twice and Strikes at a creature. On a successful Strike, the target increases its frightened condition by 1.</p>"},{"n":"Harvest Organics","a":"1","c":"offensive","t":["manipulate"],"f":"","d":"<p><strong>Requirements</strong> The Harvest is within reach of a dead creature</p><hr><p><strong>Effect</strong> The Harvest strips flesh from bone with startling precision, fusing it into its body. The Harvest gains temporary Hit Points equal to double the creature's level for 1 minute; this effect is cumulative, resetting the duration each time the ability is used, and can give the Harvest up to a maximum of 30 temporary Hit Points at a time.</p>"},{"n":"Malformed Scream","a":"2","c":"offensive","t":["auditory","emotion","fear","mental"],"f":"","d":"<p>The Harvest lets out a strained shriek that is equal parts malfunctioning robot and decaying windpipes. All creatures within 120 feet must make a DC 26 Will save or be Frightened 2 for 1 minute (Frightened 3 on a critical failure). Creatures are then immune to Malformed Scream for 24 hours.</p>"},{"n":"Moonside Cleaner","a":null,"c":"offensive","t":[],"f":"","d":"<p>The Harvest's command to clean is always its first priority. When it sees a mess being created, it must succeed at a DC 23 Will save or spend an action cleaning.</p>"},{"n":"Reconfigurable Skeleton","a":null,"c":"offensive","t":[],"f":"","d":"<p>The Harvest can Squeeze through spaces as if it were a Small creature.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/IcTl5hSPXijp0MWc":{"description":"<p>The screen erupts into static shaped vaguely like the outline of a person with only half a head.</p>","disable":"<p>DC 26 Religion or DC 26 Occultism (to ward off the haunt)</p>","abilities":[{"n":"Dread Reading","a":"r","c":"defensive","t":["emotion","fear","illusion","mental","occult"],"f":"","d":"<p><strong>Trigger</strong> A creature activates a device with a screen aboard Moonside-250</p><hr><p><strong>Effect</strong> A silhouette with a single, glowing white eye takes shape in the static and probes the triggering creature's mind. The target must attempt a DC 26 Will save. Regardless of the result, the creature experiences an intrusive thought: \"Stay here forever.\"</p><hr><p><strong>Critical Success</strong> The creature is unaffected.</p>\n<p><strong>Success</strong> The creature feels eyes watching them and panics as the eerie gaze seems to bore into their flesh. The creature takes 1d8+2 mental damage and is Frightened 1.</p>\n<p><strong>Failure</strong> The creature feels their deepest self being perceived. Ask the creature a question; the first time a creature fails against this haunt, the question is \"What is the worst thing to ever happen to you?\" Future questions build off this topic, such as \"How old were you?\", \"Did you deserve it?\", or \"Do you dream of it?\" The creature must answer honestly but doesn't have to respond out loud. The creature takes 2d8+4 mental damage and is Frightened 2.</p>\n<p><strong>Critical Failure</strong> The creature feels their sense of self fading as they gaze at the image in the static. The creature is asked three questions, takes 4d8+8 mental damage, is frightened 2 and Fleeing for 3 rounds, and is exposed to the Watcher's Stare curse.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/FLnsps36KbyIPUP0":{"notes":{"per":"heatsense (precise) 60 feet, no vision"},"abilities":[{"n":"Heatsense","a":null,"c":"interaction","t":[],"f":"","d":"<p>The vent viper can't see via vision but can detect creatures that emit heat warmer than 60 degrees as a precise sense. When environmental protections are active on a creature's armor, they block the vent viper's ability to sense the wearer.</p>"},{"n":"Vent Viper Venom","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p><strong>Saving Throw</strong> DC 17 Fortitude</p>\n<p><strong>Maximum Duration</strong> 4 rounds</p>\n<p><strong>Stage 1</strong> 1d6 poison damage and Dazzled (1 round)</p>\n<p><strong>Stage 2</strong> 1d6 poison damage and Blinded</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/nDnd1yO3ivhYolA5":{"description":"<p>A pool of deep, foul water attempts to drown creatures that enter it.</p>","disable":"<p>DC 21 Nature or DC 21 Religion and cast a 1st-rank or higher spell from the divine or primal traditions to cleanse the pool</p>","routine":"<p>(1 action) On its initiative, the Well of Roqorolos attempts to pull down each creature within it (as Drown). A creature in the well that is pulled under has to hold its breath to avoid drowning.</p><p>A creature in the water can attempt a DC 18 Athletics check to Swim 10 feet. On a critical failure, the creature sinks 5 feet. A creature that Swims out of the well escapes the hazard and is Prone in a space adjacent to the pool. Other creatures can Aid the creature, typically by using a rope or similar aid, or attempt to pull the creature out with their own DC 18 Athletics check, with the same results as if the creature attempted the check.</p>","stealthNote":"<p>(trained) (or –10 and no minimum proficiency if the surface is disturbed)</p>","abilities":[{"n":"Drown","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature enters the water</p><hr><p><strong>Effect</strong> The creature sinks underwater and must attempt a DC 16 Fortitude save. The trap then rolls initiative.</p>\n<p><strong>Failure</strong> The creature is pulled 5 feet down.</p>\n<p><strong>Critical Failure</strong> The creature is pulled 10 feet down.</p>"}]},"sf2e-anachronism.tales-from-the-vast-bestiary/9I22cN369SkyandY":{"lang":["Coshyco"],"gear":["Knife","Medpatch (Commercial) (2)"],"abilities":[{"n":"Absorb Shock","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Yorun would take bludgeoning damage</p><hr><p><strong>Effect</strong> Yorun absorbs the shock of the blow into its flesh, avoiding broken bones or other significant damage. They gain resistance 2 to bludgeoning for the triggering attack.</p>"},{"n":"Adjust Shape","a":"2","c":"offensive","t":["manipulate"],"f":"","d":"<p>Yorun rearranges their skeleton to adapt to their circumstances. They choose between squat, lanky, or flexible. If they take on the squat shape, they gain a +2 circumstance bonus to Athletics checks to Force open. If they choose lanky, they gain a +2 circumstance bonus to Acrobatics checks to Squeeze. If they choose flexible, their reach increases to 10 feet with held melee weapons.</p>"}]}});
